import{c as l,Q as a,j as e,m as o}from"./chunks/framework.DOi4mjdC.js";const i="/assets/zh-cn_image_0000002394102925.Bklbi5WV.png",s="/assets/zh-cn_image_0000002394115169.B72HUvO9.png",r="/assets/zh-cn_image_0000002394160225.D_9uRAD7.png",u="/assets/zh-cn_image_0000002394120757.CyyePzhV.png",M=JSON.parse('{"title":"Matmul高阶API使能MTE2 Preload","description":"","frontmatter":{},"headers":[{"level":1,"title":"Matmul高阶API使能MTE2 Preload","slug":"matmul高阶api使能mte2-preload"},{"level":2,"title":"案例介绍","slug":"案例介绍"},{"level":2,"title":"获取性能数据","slug":"获取性能数据"},{"level":2,"title":"分析主要瓶颈点","slug":"分析主要瓶颈点"},{"level":2,"title":"设计优化方案","slug":"设计优化方案"},{"level":2,"title":"验证优化方案性能收益","slug":"验证优化方案性能收益"},{"level":2,"title":"总结","slug":"总结"}],"relativePath":"guide/算子实践参考/优秀实践/Matmul性能调优案例/Matmul高阶API使能MTE2-Preload.md","filePath":"guide/算子实践参考/优秀实践/Matmul性能调优案例/Matmul高阶API使能MTE2-Preload.md"}'),p={name:"guide/算子实践参考/优秀实践/Matmul性能调优案例/Matmul高阶API使能MTE2-Preload.md"};function n(d,t,g,c,h,m){return a(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="matmul高阶api使能mte2-preload" tabindex="-1">Matmul高阶API使能MTE2 Preload <a class="header-anchor" href="#matmul高阶api使能mte2-preload" aria-label="Permalink to &quot;Matmul高阶API使能MTE2 Preload&quot;">​</a></h1><h2 id="案例介绍" tabindex="-1">案例介绍 <a class="header-anchor" href="#案例介绍" aria-label="Permalink to &quot;案例介绍&quot;">​</a></h2><p>本案例呈现了在矩阵乘算子场景中，使用Matmul高阶API进行矩阵乘法计算，使能MTE2 Preload对算子性能的提升效果**。**通过MatmulConfig中的doMTE2Preload参数开启矩阵M或N方向的预加载功能，预加载即在MTE2间隙提前加载A矩阵/B矩阵数据，开启预加载功能后，可以减少MTE2间隙，提升算子性能。doMTE2Preload参数的详细介绍请参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/MatmulConfig.md" target="_blank" rel="noreferrer">MatmulConfig</a>。</p><ul><li><p>使能MTE2 Preload的适用场景</p><p>MTE2流水间隙较大，且M或N数值较大时。</p></li><li><p>使能MTE2 Preload的约束条件</p><ul><li>仅在使用MDL模板和SpecialMDL模板时，MTE2 Preload有效。</li><li>开启M或N方向预加载功能时，需保证K方向数据全载，且M或N方向开启DoubleBuffer。</li><li>K方向数据全载的条件是singleK &lt;= baseK * stepK。</li><li>M方向开启DoubleBuffer的条件是depthA1 = stepM * stepK * 2。</li><li>N方向开启DoubleBuffer的条件是depthB1 = stepN * stepK * 2。</li></ul></li></ul><p>本案例的算子规格如下：</p><p><strong>表 1</strong> 算子规格</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;输入&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;Shape&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;Data type&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;Format&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;a&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;128, 512&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;float16&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;b&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;512, 24576&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;float16&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><p>当前案例使用的AI处理器共24个核，算子中使能高阶API Matmul的纯Cube模式。使用MDL模板，Tiling参数如下：</p><ul><li>原始shape：M=128, N= 24576, K=512。</li><li>单核shape：singleCoreM=128，singleCoreN=1024，singleCoreK=512。</li><li>基本块shape：baseM=128，baseN=128，baseK=64。</li><li>L1缓存相关Tiling参数：stepM=1，stepN=1，stepKa=8，stepKb=8，depthA1=8，depthB1=16。</li></ul><h2 id="获取性能数据" tabindex="-1">获取性能数据 <a class="header-anchor" href="#获取性能数据" aria-label="Permalink to &quot;获取性能数据&quot;">​</a></h2><p>使用msProf工具获取<a href="./../../性能分析/获取性能数据.html#section17259539153513">算子仿真流水图</a>和<a href="./../../性能分析/获取性能数据.html#section17953123893415">上板Profiling</a>数据，重点分析Cube，Fixpipe的流水情况。</p><h2 id="分析主要瓶颈点" tabindex="-1">分析主要瓶颈点 <a class="header-anchor" href="#分析主要瓶颈点" aria-label="Permalink to &quot;分析主要瓶颈点&quot;">​</a></h2><ul><li>优化前的流水图如下，M和K方向全载，因此A矩阵只搬运一次。由于N较大，B矩阵会搬运多次，可以看到单次MTE2间存在间隙。<img src="'+i+'" alt=""></li><li>优化前的Profiling数据如下，aic_time平均耗时30.88us。<img src="'+s+`" alt=""></li></ul><h2 id="设计优化方案" tabindex="-1">设计优化方案 <a class="header-anchor" href="#设计优化方案" aria-label="Permalink to &quot;设计优化方案&quot;">​</a></h2><p>使能MTE2 Preload功能：在创建Matmul对象时，开启doMTE2Preload开关。使能MTE2 Preload的完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_libraries/00_matrix/matmul_preload" target="_blank" rel="noreferrer">M方向预加载Matmul算子样例</a>。具体步骤如下：</p><ol><li><p>配置MDL模板参数，将其中的doMTE2Preload参数设置为2，使能N方向Preload功能。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> // preloadMode = 2</span></span>
<span class="line"><span>static constexpr MatmulConfig MM_CFG = GetMDLConfig(false, false, preloadMode);</span></span></code></pre></div></li><li><p>基于自定义MatmulConfig模板参数，创建Matmul对象。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AscendC::Matmul&lt;AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, aType&gt;,</span></span>
<span class="line"><span>    AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, bType&gt;,</span></span>
<span class="line"><span>    AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, cType&gt;,</span></span>
<span class="line"><span>    AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, biasType&gt;, MM_CFG&gt; matmulObj;</span></span></code></pre></div></li></ol><h2 id="验证优化方案性能收益" tabindex="-1">验证优化方案性能收益 <a class="header-anchor" href="#验证优化方案性能收益" aria-label="Permalink to &quot;验证优化方案性能收益&quot;">​</a></h2><ul><li>优化后的流水图如下，Tiling参数不变，可以看到，下一次计算使用的B矩阵数据提前加载，MTE2间的间隙缩短。<img src="`+r+'" alt=""></li><li>优化后的Profiling数据如下，aic_time平均耗时28.50us，较优化前的30.88us有所下降。<img src="'+u+'" alt=""></li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>当MTE2流水间隙较大，且M或N数值较大时，可以考虑使能MTE2 Preload功能，提前加载A矩阵或B矩阵数据。</p>',20)])])}const b=l(p,[["render",n]]);export{M as __pageData,b as default};
